<?php
/**
 * Activation codes (mlm_codes): generated by members (backoffice, paid from
 * their balance) or by a superadmin (Management Admin > Activation Codes).
 * A code + PIN pays for a new account at sign-up, or places a downline in
 * the backoffice (Executive codes only). Only active codes can be used or
 * transferred; a superadmin can deactivate and reactivate unused codes, and
 * download selected codes as CSV.
 * Each code has a serial number (SN-000001) in order of generation.
 */
declare(strict_types=1);

const CODE_PACKAGES = ['membership_executive' => 'EXE', 'membership_chairmans' => 'VIP'];
const CODE_STATUSES = ['active' => 'Active', 'inactive' => 'Inactive', 'used' => 'Used'];
const CODES_PER_PAGE = 25;
const CODES_MAX_BATCH = 100;
/** Most codes one bulk status change or download may name explicitly ("all matching" has no limit). */
const CODES_MAX_SELECTION = 500;
/** Most codes in one CSV download (admin_export_codes). */
const CODES_MAX_EXPORT = 10000;
/** Wrong code/PIN guesses allowed per IP address in CODE_GUESS_WINDOW seconds. */
const CODE_GUESS_LIMIT = 10;
const CODE_GUESS_WINDOW = 900;
/** No 0/O or 1/I, so codes can be read out and typed without mix-ups. */
const CODE_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';

/* ---------------------------------------------------------------------
 * Rate limits (rate_limits table)
 * ------------------------------------------------------------------- */

/** Whether $bucket already has $max hits in the current window. */
function rate_limited(string $bucket, int $max, int $window): bool
{
    return (bool) db_value('SELECT 1 FROM rate_limits WHERE bucket = ? AND hits >= ? AND window_start > NOW() - INTERVAL ? SECOND', [$bucket, $max, $window]);
}

/** Count one hit; a window that has ended starts again from 1. */
function rate_limit_hit(string $bucket, int $window): void
{
    db_run('INSERT INTO rate_limits (bucket, hits, window_start) VALUES (?, 1, NOW())
            ON DUPLICATE KEY UPDATE
              hits = IF(window_start <= NOW() - INTERVAL ? SECOND, 1, hits + 1),
              window_start = IF(window_start <= NOW() - INTERVAL ? SECOND, NOW(), window_start)',
        [$bucket, $window, $window]);
}

/* ---------------------------------------------------------------------
 * Generating and checking codes (superadmin)
 * ------------------------------------------------------------------- */

/** SN-000123 for serial 123. */
function code_serial(int $serial): string
{
    return 'SN-' . str_pad((string) $serial, 6, '0', STR_PAD_LEFT);
}

/** "Executive Member" / "Chairman's Circle" for a package key. */
function code_package_label(string $package): string
{
    return $package === 'membership_chairmans' ? "Chairman's Circle" : 'Executive Member';
}

/** A new code like EVO88-VIP-K7M2Q9XA that no other code uses. */
function new_activation_code(string $package): string
{
    do {
        $tail = '';
        for ($i = 0; $i < 8; $i++) {
            $tail .= CODE_ALPHABET[random_int(0, strlen(CODE_ALPHABET) - 1)];
        }
        $code = 'EVO88-' . CODE_PACKAGES[$package] . '-' . $tail;
    } while (db_value('SELECT 1 FROM mlm_codes WHERE code = ?', [$code]));
    return $code;
}

/** The backoffice account for an account ID (MMM-…) or a username (with or without @). */
function find_code_owner(string $ref): ?array
{
    $ref = trim($ref);
    if ($ref === '') {
        $ref = 'MMM-88001';
    }
    return db_one('SELECT a.id, a.username, a.account_name, a.user_id, u.name AS user_name FROM mlm_accounts a JOIN users u ON u.id = a.user_id WHERE a.id = ? OR a.username = ?',
        [strtoupper($ref), strtolower(ltrim($ref, '@'))]);
}

/**
 * Generate codes for a package into a backoffice account's vault, active or
 * inactive. Returns ['owner' => account row, 'codes' => [['serial', 'code', 'pin'], ...]].
 */
function admin_generate_codes(array $admin, string $package, int $quantity, string $ownerRef, string $status = 'active'): array
{
    if (!isset(CODE_PACKAGES[$package])) {
        throw new InvalidArgumentException('Choose the package the codes activate.');
    }
    if (!in_array($status, ['active', 'inactive'], true)) {
        throw new InvalidArgumentException('New codes are either active or inactive.');
    }
    if ($quantity < 1 || $quantity > CODES_MAX_BATCH) {
        throw new InvalidArgumentException('Generate between 1 and ' . CODES_MAX_BATCH . ' codes at a time.');
    }
    $owner = find_code_owner($ownerRef);
    if (!$owner) {
        throw new InvalidArgumentException('No backoffice account has that ID or username.');
    }
    $value = (float) checkout_item($package)['price'];
    $label = 'Php ' . number_format($value) . ' ' . code_package_label($package) . ' Package';

    $codes = db_tx(function () use ($admin, $package, $quantity, $owner, $value, $label, $status) {
        $made = [];
        for ($i = 0; $i < $quantity; $i++) {
            $code = new_activation_code($package);
            $pin = rand_digits(6);
            db_run('INSERT INTO mlm_codes (code, pin, owner_account_id, package, package_type, value, status, issued_by, generated_date) VALUES (?, ?, ?, ?, ?, ?, ?, ?, CURDATE())',
                [$code, $pin, $owner['id'], $package, $label, $value, $status, $admin['id']]);
            $made[] = ['serial' => code_serial((int) db()->lastInsertId()), 'code' => $code, 'pin' => $pin];
        }
        return $made;
    });
    $what = $quantity . ' ' . ($status === 'inactive' ? 'inactive ' : '') . code_package_label($package) . ' activation code' . ($quantity === 1 ? '' : 's');
    add_audit('Generated ' . $what . ' for @' . $owner['username'] . ' (' . $owner['id'] . ')', $admin['id']);
    if ($owner['user_id'] !== $admin['id']) {
        add_audit('88MMM Management added ' . $what . ' to your vault', $owner['user_id'], $owner['id']);
    }
    return ['owner' => $owner, 'codes' => $codes];
}

/**
 * Activate or deactivate an unused code. Returns the code row after the change.
 * Used codes keep their status.
 */
function admin_set_code_status(array $admin, string $code, string $status): array
{
    if (!in_array($status, ['active', 'inactive'], true)) {
        throw new InvalidArgumentException('A code can only be made active or inactive.');
    }
    $row = db_one('SELECT c.*, a.user_id AS owner_user_id FROM mlm_codes c JOIN mlm_accounts a ON a.id = c.owner_account_id WHERE c.code = ?', [strtoupper(trim($code))]);
    if (!$row) {
        throw new InvalidArgumentException('No activation code ' . $code . ' exists.');
    }
    if ($row['status'] === 'used') {
        throw new InvalidArgumentException('This code has already been used, so its status can\'t change.');
    }
    if ($row['status'] !== $status) {
        // Only an unused code changes, even if someone used it a moment ago.
        db_run('UPDATE mlm_codes SET status = ? WHERE code = ? AND status <> "used"', [$status, $row['code']]);
        $verb = $status === 'active' ? 'activated' : 'deactivated';
        add_audit('Activation code ' . $row['code'] . ' (' . code_serial((int) $row['serial']) . ') ' . $verb, $admin['id']);
        if ($row['owner_user_id'] !== $admin['id']) {
            add_audit('88MMM Management ' . $verb . ' your activation code ' . $row['code'], $row['owner_user_id'], $row['owner_account_id']);
        }
    }
    return db_one('SELECT * FROM mlm_codes WHERE code = ?', [$row['code']]);
}

/** Everything known about one code, for the checker. $pin null = don't check it. */
function admin_check_code(string $code, ?string $pin): ?array
{
    $row = db_one('SELECT c.*, a.username AS owner_username, a.account_name AS owner_account_name, o.name AS owner_name,
                          i.name AS issuer_name, u.name AS used_user_name, u.email AS used_user_email
                   FROM mlm_codes c
                   JOIN mlm_accounts a ON a.id = c.owner_account_id
                   JOIN users o ON o.id = a.user_id
                   LEFT JOIN users i ON i.id = c.issued_by
                   LEFT JOIN users u ON u.id = c.used_by_user_id
                   WHERE c.code = ?', [strtoupper(trim($code))]);
    if (!$row) {
        return null;
    }
    // A transfer records "Transferred to …" in used_by while the code stays unused.
    $transferred = $row['status'] !== 'used' && str_starts_with((string) $row['used_by'], 'Transferred to ');
    return [
        'serial' => code_serial((int) $row['serial']),
        'code' => $row['code'],
        'package' => $row['package'],
        'packageLabel' => code_package_label($row['package']),
        'value' => (float) $row['value'],
        'status' => $row['status'],
        'statusLabel' => CODE_STATUSES[$row['status']] ?? $row['status'],
        'generatedDate' => $row['generated_date'],
        'issuedBy' => $row['issued_by'] ? ($row['issuer_name'] ?? 'Deleted admin') : 'Bought in the backoffice',
        'owner' => ['id' => $row['owner_account_id'], 'username' => $row['owner_username'], 'name' => $row['owner_name']],
        'usedBy' => $row['status'] === 'used' ? (string) $row['used_by'] : null,
        'usedByAccount' => $row['used_by_user_id'] ? ['id' => $row['used_by_user_id'], 'name' => $row['used_user_name'], 'email' => $row['used_user_email']] : null,
        'usedAt' => $row['status'] === 'used' && $row['used_at'] ? fmt_datetime($row['used_at']) : null,
        'lastTransfer' => $transferred ? ['to' => substr((string) $row['used_by'], 15), 'at' => $row['used_at'] ? fmt_datetime($row['used_at']) : null] : null,
        'pinMatches' => $pin === null || $pin === '' ? null : hash_equals((string) $row['pin'], trim($pin)),
    ];
}

/** 123 for "SN-000123", "SN000123", "000123" or "123"; null for anything else. */
function code_serial_parse(string $text): ?int
{
    return preg_match('/^(?:SN-?)?0*(\d{1,9})$/i', trim($text), $m) ? (int) $m[1] : null;
}

/**
 * The code logs' serial range from what was typed in "Serial from" and "to"
 * (either may be empty for an open end). A reversed range is put the right
 * way round. Returns [from|null, to|null, error message|null].
 */
function code_serial_range(string $from, string $to): array
{
    $a = trim($from) === '' ? null : code_serial_parse($from);
    $b = trim($to) === '' ? null : code_serial_parse($to);
    if ((trim($from) !== '' && $a === null) || (trim($to) !== '' && $b === null)) {
        return [null, null, 'Type serials like SN-000001, or just the number (1).'];
    }
    if ($a !== null && $b !== null && $a > $b) {
        [$a, $b] = [$b, $a];
    }
    return [$a, $b, null];
}

/**
 * One page of the code logs, newest first. Filters: q (serial, code, owner
 * ID/username/name, used by), status, package, serial range (from / to).
 */
function admin_list_codes(string $q, string $status, string $package, int $page, ?int $from = null, ?int $to = null): array
{
    [$sql, $params] = admin_code_filter($q, $status, $package, $from, $to);
    $total = (int) db_value("SELECT COUNT(*) $sql", $params);
    $offset = (max(1, $page) - 1) * CODES_PER_PAGE;
    $rows = db_all("SELECT c.serial, c.code, c.pin, c.package, c.value, c.status, c.used_by, c.used_at, c.generated_date, c.issued_by,
                           c.owner_account_id, a.username AS owner_username, o.name AS owner_name, u.email AS used_by_email
                    $sql ORDER BY c.serial DESC LIMIT " . CODES_PER_PAGE . " OFFSET $offset", $params);
    return [$rows, $total];
}

/**
 * The code logs as a CSV file for download: the selected codes, or every code
 * matching the logs filters ($filter = ['q', 'status', 'package', 'from', 'to']).
 * The file holds PINs, so each download is written to the audit log.
 * Returns ['csv' => text, 'count' => n, 'filename' => name].
 */
function admin_export_codes(array $admin, array $codes, ?array $filter = null): array
{
    if ($filter !== null) {
        [$from, $to, $error] = code_serial_range(str_in($filter, 'from', 20), str_in($filter, 'to', 20));
        if ($error !== null) {
            throw new InvalidArgumentException($error);
        }
        [$sql, $params] = admin_code_filter(str_in($filter, 'q', 100), str_in($filter, 'status', 20), str_in($filter, 'package', 40), $from, $to);
    } else {
        $codes = array_values(array_unique(array_filter(array_map(fn ($c) => strtoupper(trim((string) $c)), $codes), fn ($c) => $c !== '' && strlen($c) <= 40)));
        if (!$codes) {
            throw new InvalidArgumentException('Select at least one code.');
        }
        if (count($codes) > CODES_MAX_SELECTION) {
            throw new InvalidArgumentException('Select at most ' . CODES_MAX_SELECTION . ' codes at a time, or use "Select all matching".');
        }
        [$sql, $params] = admin_code_filter('', '', '');
        $sql .= ' AND c.code IN (' . implode(',', array_fill(0, count($codes), '?')) . ')';
        $params = array_merge($params, $codes);
    }
    $n = (int) db_value("SELECT COUNT(*) $sql", $params);
    if ($n === 0) {
        throw new InvalidArgumentException('None of these codes exist any more.');
    }
    if ($n > CODES_MAX_EXPORT) {
        throw new InvalidArgumentException('That is ' . number_format($n) . ' codes. Download at most ' . number_format(CODES_MAX_EXPORT) . ' at a time: narrow the filters.');
    }
    $rows = db_all("SELECT c.serial, c.code, c.pin, c.package, c.value, c.status, c.used_by, c.used_at, c.generated_date,
                           c.owner_account_id, a.username AS owner_username, o.name AS owner_name, u.email AS used_by_email
                    $sql ORDER BY c.serial", $params);

    $lines = [csv_line(['Serial', 'Package', 'Value', 'Code', 'PIN', 'Status', 'Owner Account', 'Owner Username', 'Owner Name', 'Used By', 'Used By Email', 'Date Used', 'Generated'])];
    foreach ($rows as $r) {
        $used = $r['status'] === 'used';
        $lines[] = csv_line([
            code_serial((int) $r['serial']), code_package_label($r['package']), number_format((float) $r['value'], 2, '.', ''),
            $r['code'], $r['pin'], CODE_STATUSES[$r['status']] ?? $r['status'],
            $r['owner_account_id'], $r['owner_username'], $r['owner_name'],
            $used ? $r['used_by'] : '', $used ? $r['used_by_email'] : '', $used ? $r['used_at'] : '', $r['generated_date'],
        ]);
    }
    $count = count($rows);
    add_audit('Downloaded ' . $count . ' activation code' . ($count === 1 ? '' : 's') . ' as CSV: ' . code_serial_ranges(array_map('intval', array_column($rows, 'serial'))), $admin['id']);
    return ['csv' => implode("\r\n", $lines) . "\r\n", 'count' => $count, 'filename' => 'activation-codes-' . date('Y-m-d') . '.csv'];
}

/**
 * FROM/WHERE for the code logs filters, as [sql, params]. The WHERE clause is
 * always present, so callers can add "AND …". $from / $to: serial range
 * (inclusive; null for an open end), as code_serial_range() returns it.
 */
function admin_code_filter(string $q, string $status, string $package, ?int $from = null, ?int $to = null): array
{
    $where = ['1 = 1'];
    $params = [];
    if ($q !== '') {
        $like = '%' . addcslashes($q, '%_\\') . '%';
        $bySerial = preg_match('/^(?:SN-?)?0*(\d{1,9})$/i', $q, $m) ? (int) $m[1] : -1;
        $where[] = '(c.serial = ? OR c.code LIKE ? OR c.owner_account_id = ? OR a.username LIKE ? OR o.name LIKE ? OR c.used_by LIKE ?)';
        array_push($params, $bySerial, $like, strtoupper($q), $like, $like, $like);
    }
    if (isset(CODE_STATUSES[$status])) {
        $where[] = 'c.status = ?';
        $params[] = $status;
    }
    if (isset(CODE_PACKAGES[$package])) {
        $where[] = 'c.package = ?';
        $params[] = $package;
    }
    if ($from !== null) {
        $where[] = 'c.serial >= ?';
        $params[] = $from;
    }
    if ($to !== null) {
        $where[] = 'c.serial <= ?';
        $params[] = $to;
    }
    $sql = 'FROM mlm_codes c JOIN mlm_accounts a ON a.id = c.owner_account_id JOIN users o ON o.id = a.user_id'
        . ' LEFT JOIN users u ON u.id = c.used_by_user_id'
        . ' WHERE ' . implode(' AND ', $where);
    return [$sql, $params];
}

/** Every unused code matching the code logs filters ("select all matching"). */
function admin_matching_codes(string $q, string $status, string $package, ?int $from = null, ?int $to = null): array
{
    [$sql, $params] = admin_code_filter($q, $status, $package, $from, $to);
    return array_column(db_all("SELECT c.code $sql AND c.status <> 'used'", $params), 'code');
}

/** "SN-000014–SN-000020, SN-000025" for a list of serials (shortened when long). */
function code_serial_ranges(array $serials): string
{
    sort($serials);
    $parts = [];
    for ($i = 0, $n = count($serials); $i < $n; $i = $j) {
        for ($j = $i + 1; $j < $n && $serials[$j] === $serials[$j - 1] + 1; $j++) {
        }
        $parts[] = code_serial($serials[$i]) . ($j - 1 > $i ? '–' . code_serial($serials[$j - 1]) : '');
    }
    $shown = array_slice($parts, 0, 8);
    return implode(', ', $shown) . (count($parts) > 8 ? ' and ' . (count($parts) - 8) . ' more ranges' : '');
}

/**
 * Activate or deactivate several codes at once. Used codes and codes already
 * in that status are left as they are.
 * Returns ['changed' => n, 'already' => n, 'used' => n, 'missing' => n].
 */
function admin_set_codes_status(array $admin, array $codes, string $status): array
{
    if (!in_array($status, ['active', 'inactive'], true)) {
        throw new InvalidArgumentException('Codes can only be made active or inactive.');
    }
    $codes = array_values(array_unique(array_filter(array_map(fn ($c) => strtoupper(trim((string) $c)), $codes), fn ($c) => $c !== '' && strlen($c) <= 40)));
    if (!$codes) {
        throw new InvalidArgumentException('Select at least one code.');
    }
    $result = db_tx(function () use ($codes, $status) {
        $found = [];
        foreach (array_chunk($codes, 500) as $chunk) {
            $marks = implode(',', array_fill(0, count($chunk), '?'));
            $found = array_merge($found, db_all("SELECT c.code, c.serial, c.status, c.owner_account_id, a.user_id AS owner_user_id
                FROM mlm_codes c JOIN mlm_accounts a ON a.id = c.owner_account_id WHERE c.code IN ($marks) FOR UPDATE", $chunk));
        }
        $change = array_values(array_filter($found, fn ($r) => $r['status'] !== 'used' && $r['status'] !== $status));
        foreach (array_chunk(array_column($change, 'code'), 500) as $chunk) {
            $marks = implode(',', array_fill(0, count($chunk), '?'));
            db_run("UPDATE mlm_codes SET status = ? WHERE code IN ($marks) AND status <> 'used'", array_merge([$status], $chunk));
        }
        return [
            'changed' => $change,
            'already' => count(array_filter($found, fn ($r) => $r['status'] === $status)),
            'used' => count(array_filter($found, fn ($r) => $r['status'] === 'used')),
            'missing' => count($codes) - count($found),
        ];
    });

    $changed = $result['changed'];
    if ($changed) {
        $verb = $status === 'active' ? 'activated' : 'deactivated';
        $n = count($changed);
        add_audit(ucfirst($verb) . ' ' . $n . ' activation code' . ($n === 1 ? '' : 's') . ': ' . code_serial_ranges(array_map('intval', array_column($changed, 'serial'))), $admin['id']);
        $byOwner = [];
        foreach ($changed as $r) {
            $byOwner[$r['owner_account_id']] ??= ['user' => $r['owner_user_id'], 'n' => 0];
            $byOwner[$r['owner_account_id']]['n']++;
        }
        foreach ($byOwner as $accountId => $o) {
            if ($o['user'] !== $admin['id']) {
                add_audit('88MMM Management ' . $verb . ' ' . ($o['n'] === 1 ? 'one' : $o['n']) . ' of your activation codes', $o['user'], $accountId);
            }
        }
    }
    return ['changed' => count($changed), 'already' => $result['already'], 'used' => $result['used'], 'missing' => $result['missing']];
}

/* ---------------------------------------------------------------------
 * Paying for a new account with a code
 * ------------------------------------------------------------------- */

/**
 * Create an account from the sign-up form paid with an activation code +
 * PIN. The code is used up in the same transaction. Returns the user row.
 */
function signup_with_code(array $in): array
{
    $reg = registration_request($in);
    $code = strtoupper(trim(str_in($in, 'activationCode', 40)));
    $pin = trim(str_in($in, 'activationPin', 10));
    if ($code === '' || $pin === '') {
        throw new InvalidArgumentException('Please enter your activation code and its PIN.');
    }
    $bucket = 'code-guess:' . ($_SERVER['REMOTE_ADDR'] ?? 'unknown');
    if (rate_limited($bucket, CODE_GUESS_LIMIT, CODE_GUESS_WINDOW)) {
        throw new InvalidArgumentException('Too many incorrect activation codes. Please wait 15 minutes and try again.');
    }

    // [user id, code row] or an error message ('wrong' = unknown code or wrong PIN).
    try {
        $result = db_tx(function () use ($reg, $code, $pin) {
            $row = db_one('SELECT * FROM mlm_codes WHERE code = ? FOR UPDATE', [$code]);
            if (!$row || !hash_equals((string) $row['pin'], $pin)) {
                return 'wrong';
            }
            if ($row['status'] === 'used') {
                return 'This activation code has already been used.';
            }
            if ($row['status'] !== 'active') {
                return 'This activation code isn\'t active yet. Ask your referrer or the 88MMM administrator to activate it.';
            }
            if ($row['package'] !== $reg['package']) {
                return 'This is a ' . code_package_label($row['package']) . ' code. Select the ' . code_package_label($row['package']) . ' package to use it.';
            }
            $userId = create_registered_account($reg);
            db_run('UPDATE mlm_codes SET status = "used", used_by = ?, used_by_user_id = ?, used_at = NOW() WHERE code = ?', [$reg['name'] . ' (sign-up)', $userId, $code]);
            return [$userId, $row];
        });
    } catch (PDOException $e) {
        // 1062 on the email key: it was registered a moment ago (the code stays unused).
        if (($e->errorInfo[1] ?? null) !== 1062 || !str_contains((string) ($e->errorInfo[2] ?? ''), 'email')) {
            throw $e;
        }
        throw new InvalidArgumentException('An account with this email already exists. Please sign in.');
    }
    if ($result === 'wrong') {
        rate_limit_hit($bucket, CODE_GUESS_WINDOW);
        throw new InvalidArgumentException('That activation code and PIN don\'t match. Check both and try again.');
    }
    if (is_string($result)) {
        throw new InvalidArgumentException($result);
    }

    [$userId, $row] = $result;
    update_member_profile($userId, ['membershipStatus' => 'Active', 'renewalDate' => date('M Y', strtotime('+1 year'))]);
    add_audit('Account activated with activation code ' . $code . ' (' . code_package_label($row['package']) . ')', $userId);
    $owner = db_one('SELECT id, user_id FROM mlm_accounts WHERE id = ?', [$row['owner_account_id']]);
    if ($owner && $owner['user_id'] !== $userId) {
        add_audit('Activation code ' . $code . ' was used by new member ' . $reg['name'], $owner['user_id'], $owner['id']);
    }
    return db_one('SELECT * FROM users WHERE id = ?', [$userId]);
}
